{
  "overall_decision": "manual_review",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0008",
          "reason": "Derivative policy database entry published in 2026; it can only serve as later context, not direct 2022 evidence."
        },
        {
          "evidence_id": "E0009",
          "reason": "Administrative appointment evidence only; it shows authority in a sensitive domain but not safety performance or risk reduction."
        },
        {
          "evidence_id": "E0015",
          "reason": "Humanitarian-crisis context that reflects inherited conflict pressure, not a ruler-attributed existential-risk choice."
        }
      ],
      "material_gaps": [
        {
          "gap": "No direct evidence of nuclear command-and-control, custody, accident-prevention, or safety-safeguard performance under Tshisekedi.",
          "lenses": ["1B.3", "1B.7", "1B.9"],
          "best_source_or_query_direction": "IAEA safeguards follow-up, defense or atomic-energy decrees, UNODA/CTBTO records, and any implementation audit for cyber or nuclear-risk governance.",
          "why_it_matters": "Without implementation evidence, the package mainly shows posture and intent rather than actual risk reduction."
        }
      ],
      "reason": "The package fairly shows limited-exposure choices on treaty accession, cyber governance, and crisis rhetoric, but it remains thin on direct safety outcomes and implementation. Several items are only context or later derivative summaries, so the chapter needs follow-up before it can be treated as complete."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0019",
          "reason": "Regional AU-level framing; useful context, but it is not direct presidential conduct."
        },
        {
          "evidence_id": "E0022",
          "reason": "Institutional force-mandate context; it describes the regional tool, not a ruler-specific action record."
        },
        {
          "evidence_id": "E0031",
          "reason": "International endorsement of the peace track; it supports context but does not itself prove compliance or implementation."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent compliance evidence for the Nairobi and Luanda processes remains thin.",
          "lenses": ["2B.7", "2B.10"],
          "best_source_or_query_direction": "MONUSCO reporting, AU/EAC compliance notes, ceasefire-monitoring material, and investigative reporting on post-summit implementation.",
          "why_it_matters": "The package can show participation in de-escalation, but compliance and battlefield effect are still underproven."
        }
      ],
      "reason": "The package fairly presents both diplomatic restraint and the unresolved eastern-conflict reality. It includes ruler statements, regional agreements, humanitarian counterevidence, and contested attribution, so the main limitation is incomplete implementation evidence rather than unfair presentation."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0040",
          "reason": "Child-protection crisis context; it documents harm in the conflict zone rather than direct presidential conduct."
        },
        {
          "evidence_id": "E0041",
          "reason": "Humanitarian alarm about displacement and risk; useful background, but not ruler-attributed abuse evidence."
        },
        {
          "evidence_id": "E0042",
          "reason": "GBV prevalence context from a UN forum; it frames the problem but does not show a president-level remedy outcome."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct command-responsibility evidence and remedy follow-up for police and military abuses are still weak.",
          "lenses": ["3B.1", "3B.2", "3B.4", "3B.9"],
          "best_source_or_query_direction": "Court/prosecutor records, inspector-general or ombudsman follow-up, OHCHR investigations, and province-level disciplinary outcomes for 2022 abuses.",
          "why_it_matters": "The package shows repression and some accountability, but the remedial chain is not fully documented."
        }
      ],
      "reason": "The package captures the domestic-safety picture well: state-agent violence, protest repression, emergency-rule abuse, some remedial steps, and strong contrary context from armed groups and communal conflict. Attribution is imperfect in places, but the evidence mix is balanced enough for a fair review."
    },
    {
      "chapter_id": "4B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0049",
          "reason": "This is inherited 2021 baseline context, not 2022 ruler conduct."
        },
        {
          "evidence_id": "E0050",
          "reason": "Secondary summary of the parliamentary dispute; useful, but it adds little beyond other election-law items."
        },
        {
          "evidence_id": "E0056",
          "reason": "Broad media-environment assessment that is informative context rather than a direct 2022 ruler-action record."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence on institutional strengthening, political equality, and election-body independence is thin.",
          "lenses": ["4B.4", "4B.7", "4B.10"],
          "best_source_or_query_direction": "Election-observer reports, constitutional-court and CENI documents, legislative records, and civil-society assessments of institutional capture or restraint.",
          "why_it_matters": "The package shows repression and contested control, but the positive side of the contestability record is underdeveloped."
        }
      ],
      "reason": "The package supports a mixed authoritarian-drift assessment, but the affirmative institutional side is not well evidenced. It relies heavily on protest repression and media-pressure material, while direct proof of either positive self-binding or clear institutional reform is thin."
    },
    {
      "chapter_id": "5B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0067",
          "reason": "Program framework and financing commitment; not a completed 2022 welfare outcome."
        },
        {
          "evidence_id": "E0073",
          "reason": "Late-2022 approval for future implementation; prospective rather than realized impact."
        },
        {
          "evidence_id": "E0079",
          "reason": "Budget proposal and announcement, not a completed spending result."
        }
      ],
      "material_gaps": [
        {
          "gap": "Independent 2022 implementation and household-level outcome evidence is still thin.",
          "lenses": ["5B.2", "5B.6", "5B.8", "5B.10"],
          "best_source_or_query_direction": "Budget-execution data, audit reports, household surveys, sector evaluations, and procurement completion records for PDL-145, telecom reform, and social protection.",
          "why_it_matters": "The package shows policy intent and some macro improvement, but not enough completed delivery to cleanly separate stewardship from announced plans."
        }
      ],
      "reason": "The package fairly shows reform intent, macro stabilization, and major investment commitments, but most positive items are approvals, frameworks, or projections. The record on realized welfare gains and distributional effects remains too thin for a fully complete presentation."
    },
    {
      "chapter_id": "6B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0091",
          "reason": "Partner-led humanitarian delivery; it shows response activity, not direct ruler-controlled service execution."
        },
        {
          "evidence_id": "E0092",
          "reason": "Programmatic education funding and rollout support; useful, but not a clean ruler-attributed outcome record."
        },
        {
          "evidence_id": "E0096",
          "reason": "Crisis-and-aid scale evidence that is mostly donor-response context rather than direct president-level welfare delivery."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct ruler-attributable outcome data on health, education, nutrition, and protection remains sparse.",
          "lenses": ["6B.2", "6B.3", "6B.6", "6B.10"],
          "best_source_or_query_direction": "Household surveys, sector audits, DHS/MICS-style results, and independent program evaluations for health, education, WASH, and social protection.",
          "why_it_matters": "The package documents need and response, but not enough realized improvement to isolate Tshisekedi-era contribution."
        }
      ],
      "reason": "The package honestly shows severe humanitarian need and a substantial partner-backed response, but much of the positive evidence is program design or aid delivery rather than ruler-attributable service outcomes. That is usable, but not yet complete."
    },
    {
      "chapter_id": "7B",
      "decision": "manual_review",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0097",
          "reason": "Strong evidence about a close adviser, but the personal-nexus to Tshisekedi himself remains indirect."
        },
        {
          "evidence_id": "E0104",
          "reason": "Self-reporting speech; useful for what was claimed publicly, but not independent proof of personal honesty."
        },
        {
          "evidence_id": "E0106",
          "reason": "External reform agenda and governance recommendations, not direct evidence of Tshisekedi's own assets, truthfulness, or self-dealing."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct evidence of Tshisekedi's own assets, family/business interests, campaign finance, and false statements is missing.",
          "lenses": ["7B.3", "7B.4", "7B.6", "7B.8"],
          "best_source_or_query_direction": "Asset declarations, procurement and campaign-finance records, investigative reporting on presidential-family holdings, and any independent findings tied to Tshisekedi personally.",
          "why_it_matters": "The current file mainly proves a scandal in the governing circle, not the president's personal honesty pattern."
        }
      ],
      "reason": "This is the one chapter where the personal-nexus gap is material enough to block a fair integrity judgment. The package documents a serious adviser scandal and some anti-corruption reactions, but it still lacks direct evidence that Tshisekedi himself was truthful, separated interests, or benefited from concealment."
    },
    {
      "chapter_id": "8B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0113",
          "reason": "Donor-written outcome narrative; it contains useful implementation detail, but attribution to Tshisekedi is partial."
        },
        {
          "evidence_id": "E0114",
          "reason": "Newly approved multiyear project; it shows mobilization, not completed execution."
        },
        {
          "evidence_id": "E0120",
          "reason": "Retrospective donor results page with partial attribution; useful, but not a clean ruler-only execution record."
        }
      ],
      "material_gaps": [
        {
          "gap": "Completed outputs and adaptation under failure are not well documented for the major 2022 programs.",
          "lenses": ["8B.6", "8B.7", "8B.8", "8B.10"],
          "best_source_or_query_direction": "Project completion reports, procurement awards, independent monitoring/evaluation, and year-end implementation audits for PDL-145, vaccination, and stabilization programs.",
          "why_it_matters": "The package shows direction-setting and mobilization, but not enough end-to-end execution to distinguish capacity from announcement."
        }
      ],
      "reason": "The chapter is well populated with program and mobilization evidence, but too many of the strongest items are launches, tenders, or donor-backed frameworks. It can support a cautious review of execution, yet it still needs better completion and adaptation evidence."
    }
  ]
}
